const events=new EventSource('/api/events');let previousSnapshot='';events.onmessage=e=>{const snapshot=JSON.stringify(JSON.parse(e.data));if(snapshot===previousSnapshot)return;const first=!previousSnapshot;previousSnapshot=snapshot;updateNavActivity(JSON.parse(e.data));updateCounts();if(pendingLookupId)refreshMetadataLookup();if(['library','review'].includes(page))refreshBulkMetadata();if(page==='studio'&&!modal.open)refreshStudioProgress(JSON.parse(e.data));if(page==='downloader')refreshDiscoveryStatus();if(page==='jobs'&&!modal.open&& !first)api('/jobs').then(jobs=>{if(page==='jobs'&&$('#job-list'))$('#job-list').innerHTML=jobs.map(jobCard).join('')||empty('No visible jobs.','Choose Show closed jobs to review the retained history.');}).catch(()=>{});};
let filesystemRevision=-1,filesystemRefreshing=false;
function galleryVersion(a){return JSON.stringify(a.images.map(im=>[im.id,im.file_id,im.cover_path,im.sha256,im.classification]));}
async function refreshFolderViews(status){
 const label=$('#filesystem-status');if(label)label.textContent=status.error||(!status.enabled?'Automatic folder indexing is disabled.':status.scanning?`Reading folder files · ${fmt(status.scanned)} / ${fmt(status.total)} albums`:'Folder files are up to date · changes appear automatically.');
 if(!status.enabled||filesystemRefreshing||status.revision===filesystemRevision)return;
 filesystemRefreshing=true;const revision=status.revision,token=generation;
 try{
  if(['library','review'].includes(page)&&$('#library-files')&&albumFilter!=='duplicates'){
   const html=await library(page==='review');if(token===generation&&$('#library-files')){const template=document.createElement('template');template.innerHTML=html;const fresh=template.content.querySelector('#library-files');if(fresh)$('#library-files').innerHTML=fresh.innerHTML;const count=template.content.querySelector('.tabs .muted');if(count&&$('.tabs .muted'))$('.tabs .muted').textContent=count.textContent;}
  }
  let fresh=null;
  if(currentAlbum&&modal.open&&$('#metadata-form')){
   const id=currentAlbum.id;fresh=await api('/albums/'+id);
   if(currentAlbum?.id===id&&modal.open&&$('.detail-gallery')){
    if(galleryVersion(fresh)!==galleryVersion(currentAlbum))$('.detail-gallery').innerHTML=albumGallery(fresh);
    Object.assign(currentAlbum,{images:fresh.images,folder:fresh.folder,cover_id:fresh.cover_id,cover_url:fresh.cover_url});
    if($('#album-files-path'))$('#album-files-path').textContent=fresh.folder;
   }
  }
  if(viewer.open&&viewerItems.length&&new Set(viewerItems.map(im=>im.album_id)).size===1){
   const old=viewerItems[viewerIndex],id=old.album_id;
   if(id){if(fresh?.id!==id)fresh=await api('/albums/'+id);const images=fresh.images.map(im=>({...im,title:fresh.title,album_id:id}));if(JSON.stringify(images)!==JSON.stringify(viewerItems)){const index=images.findIndex(im=>im.id===old.id||(old.file_id&&im.file_id===old.file_id));viewerItems=images;viewerIndex=index>=0?index:Math.min(viewerIndex,images.length-1);if(images.length)drawViewer();else viewer.close();}}
  }
  filesystemRevision=revision;
 }catch(error){console.warn('Folder refresh will retry:',error.message);}finally{filesystemRefreshing=false;}
}
events.addEventListener?.('filesystem',event=>refreshFolderViews(JSON.parse(event.data)));
document.addEventListener('click',async event=>{if(!event.target.closest('[data-action="refresh-files"]'))return;try{const status=await api('/filesystem/refresh',{method:'POST'});filesystemRevision=-1;await refreshFolderViews(status);toast('Reading current folder files. Artwork files are unchanged.');}catch(error){toast(error.message,true);}});
