function updateNavActivity(jobs){
 const link=$('nav a[data-page="downloader"]');if(!link)return;
 const active=jobs.filter(j=>['discover','download'].includes(j.kind)&&['queued','running'].includes(j.status));
 let indicator=$('.nav-activity',link);if(!active.length){indicator?.remove();return;}
 if(!indicator){indicator=document.createElement('span');indicator.className='nav-activity';link.append(indicator);}
 const running=active.filter(j=>j.status==='running').length;
 indicator.innerHTML=`<span class="activity-spinner" aria-hidden="true"></span><span>${active.length}</span>`;
 indicator.setAttribute('role','status');indicator.setAttribute('aria-label',`${running} active, ${active.length-running} queued discovery or download jobs`);indicator.title=indicator.getAttribute('aria-label');
}
api('/jobs').then(updateNavActivity).catch(()=>{});
