window.addEventListener('message',async event=>{
 if(event.source!==window||event.origin!==location.origin)return;
 if(event.data?.type==='coverly-metadata-status'){
  const message=event.data.error||'Album connected. Open a reference result, then use the Coverly extension’s Use this page in Coverly button.';
  if($('#metadata-browser-status'))$('#metadata-browser-status').textContent=message;
  toast(message,Boolean(event.data.error));
 }
 if(event.data?.type==='coverly-metadata-received'){
  const id=event.data.album_id;
  if(currentAlbum?.id===id&&modal.open){
   const a=await api('/albums/'+id);currentAlbum.soundtrack_candidates=a.soundtrack_candidates;currentAlbum.metadata_suggestions=a.metadata_suggestions;
   $('#metadata-suggestions').innerHTML=metadataSuggestions(a);$('#metadata-suggestions').scrollIntoView({block:'start'});
   if($('#metadata-browser-status'))$('#metadata-browser-status').textContent='Page received. Review the source table below and choose Use these details.';
  }else{
   const item=document.createElement('div');item.className='toast';const link=document.createElement('a');link.href='#album/'+encodeURIComponent(id);link.textContent='Browser metadata received — open album to review';item.append(link);$('#toasts').append(item);
  }
  toast('Browser credits received. Review and save to apply.');
 }
});

function metadataBridgeHelp(){return `<strong>Connect a regular Chrome/Edge tab</strong><ol><li>Open <code>chrome://extensions</code> in Chrome. Make sure Coverly Artwork Handoff is listed, enabled and version 1.1. If it is missing, enable Developer mode, choose Load unpacked and select the <code>browser-bridge</code> folder in your Coverly project.</li><li>Click Chrome’s puzzle-piece Extensions button, then pin Coverly Artwork Handoff. Its icon will appear in the toolbar.</li><li>Use the updated link below in a regular Chrome tab with an address bar. The Codex in-app browser and a standalone app window do not provide this extension toolbar.</li><li>Start Search Google + return page here. On the reference result, click the extension icon, then Use this page in Coverly.</li></ol><div class="actions">${btn('Copy updated Coverly link','copy-update-url','secondary small')}<a class="button ghost small" href="/api/browser-bridge" download>Download browser bridge</a></div><p>URL and copied-table imports work without the extension.</p>`;}
const loadedInterface=Object.fromEntries(['app.js','style.css','theme.js'].map(name=>{const el=document.querySelector(name.endsWith('.css')?`link[href*="/static/${name}"]`:`script[src*="/static/${name}"]`);return [name,el?new URL(el.src||el.href,location.href).searchParams.get('v'):null];}));
let interfaceCheckBusy=false;
async function checkInterfaceVersion(){if(interfaceCheckBusy||document.hidden)return;interfaceCheckBusy=true;try{const current=await api('/interface-version');if(Object.entries(current).some(([name,value])=>loadedInterface[name]&&loadedInterface[name]!==value))$('#interface-update').hidden=false;}catch{}finally{interfaceCheckBusy=false;}}
setInterval(checkInterfaceVersion,30000);window.addEventListener('focus',checkInterfaceVersion);document.addEventListener('visibilitychange',checkInterfaceVersion);

function connectMetadataAlbum(){if(currentAlbum&&modal.open&&document.documentElement.dataset.coverlyMetadataBridge==='1')window.postMessage({type:'coverly-metadata-connect',album_id:currentAlbum.id,title:$('#lookup-title')?.value.trim()||currentAlbum.title,open_search:false},location.origin);}
window.addEventListener('coverly-bridge-ready',connectMetadataAlbum);

let importArtworkFiles=[],importPreviewURLs=[];
function resetImportArtwork(){importPreviewURLs.forEach(url=>URL.revokeObjectURL(url));importPreviewURLs=[];importArtworkFiles=[];}
function artworkImportPicker(){return `<div class="import-file-picker"><div class="actions">${btn('Add image files…','import-files-pick','secondary small')}${btn('Add album folder…','import-folder-pick','ghost small')}</div><input id="import-files-picker" data-artwork-picker type="file" multiple accept="image/jpeg,image/png,image/webp,image/tiff,image/bmp" hidden><input id="import-folder-picker" data-artwork-picker type="file" webkitdirectory directory multiple hidden><p class="help">Choose several files with ⌘/Ctrl or Shift, or choose one album folder containing front, back and record/CD scans. Up to 100 images belong to this album.</p><div id="import-file-list" class="import-file-list" role="status">No images selected.</div></div>`;}
function renderImportFiles(){
 importPreviewURLs.forEach(url=>URL.revokeObjectURL(url));importPreviewURLs=[];const list=$('#import-file-list');if(!list)return;
 list.innerHTML=importArtworkFiles.length?`<strong>${importArtworkFiles.length} images selected · ${(importArtworkFiles.reduce((n,f)=>n+f.size,0)/1048576).toFixed(1)} MB</strong>`+importArtworkFiles.map((file,index)=>{const url=URL.createObjectURL(file);importPreviewURLs.push(url);return `<div class="import-file-row"><img src="${url}" alt="" loading="lazy"><span>${esc(file.webkitRelativePath||file.name)}<small>${Math.ceil(file.size/1024)} KB</small></span>${btn('Remove','import-remove-file','ghost small',`data-index="${index}"`)}</div>`;}).join(''):'No images selected.';
}
document.addEventListener('change',event=>{
 if(!event.target.matches('[data-artwork-picker]'))return;
 addImportArtworkFiles([...event.target.files]);event.target.value='';
});
function addImportArtworkFiles(incoming){
 const valid=incoming.filter(f=>!f.name.startsWith('.')&&/\.(?:jpe?g|png|webp|tiff?|bmp)$/i.test(f.name));
 const existing=new Map(importArtworkFiles.map(f=>[(f.webkitRelativePath||f.name)+':'+f.size+':'+f.lastModified,f]));
 valid.forEach(f=>existing.set((f.webkitRelativePath||f.name)+':'+f.size+':'+f.lastModified,f));
 if(existing.size>100){toast('Choose at most 100 images for one album.');return;}
 importArtworkFiles=[...existing.values()];
 const title=$('#import-title');if(title&&!title.value.trim()&&valid[0]?.webkitRelativePath)title.value=valid[0].webkitRelativePath.split('/')[0];
 renderImportFiles();if(incoming.length!==valid.length)toast(`${incoming.length-valid.length} unsupported or hidden files skipped.`);
}

async function pickImportFolder(){
 if(!window.pywebview?.api?.choose_artwork_folder){$('#import-folder-picker').click();return;}
 const result=await window.pywebview.api.choose_artwork_folder();if(!result)return;if(result.error)throw Error(result.error);
 const files=result.files.map(item=>{const bytes=Uint8Array.from(atob(item.data),c=>c.charCodeAt(0));const file=new File([bytes],item.name,{type:item.type,lastModified:item.modified});Object.defineProperty(file,'webkitRelativePath',{value:item.relative});return file;});
 addImportArtworkFiles(files);
}
